public class Main {
    static class Edge {
        int to, w;
        Edge(int t, int w){ this.to=t; this.w=w; }
    }
    static List<Edge>[] g;
    static int n, k;

    static int[] dfs(int u, int p, int L){
        int dp0 = 0;     // 不选 u
        int dp1 = 1;     // 选 u（计入 1）
        for (Edge e: g[u]) {
            int v = e.to, w = e.w;
            if (v == p) continue;
            int[] cv = dfs(v, u, L);
