import sys
sys.setrecursionlimit(1 << 20)

def dfs(u, p, L, adj):
    dp0, dp1 = 0, 1  # dp1 初值 +1，表示修改 u 的频率
    for v, w in adj[u]:
        if v == p:
            continue
        c0, c1 = dfs(v, u, L, adj)
        if w > L:          # 坏边：必须至少改一端
            dp0 += c1       # 不修改 u 则必须修改 v
            dp1 += min(c0, c1)  # 修改 u，v 任意
        else:               # 好边：无需额外修改
            t = min(c0, c1)
            dp0 += t
            dp1 += t
    return dp0, dp1

def check(L, adj, n, k):
    dp0, dp1 = dfs(1, 0, L, adj)
    return min(dp0, dp1) <= k

def main():
    data = list(map(int, sys.stdin.read().strip().split()))
    it = iter(data)
    n = next(it); k = next(it)
    f = [0] + [next(it) for _ in range(n)]        # 基站初始频率
    adj = [[] for _ in range(n + 1)]
    maxw = 0
    for _ in range(n - 1):
        u = next(it); v = next(it)
        w = abs(f[u] - f[v])
        if w > maxw:
            maxw = w
        adj[u].append((v, w))
        adj[v].append((u, w))
    lo, hi = 0, maxw
    while lo < hi:
        mid = (lo + hi) // 2
        if check(mid, adj, n, k):
            hi = mid
        else:
            lo = mid + 1
    print(lo)

if __name__ == "__main__":
    main()
